/**
 * O podômetro da formiga — porte de `componentes/viz/podometro.js`.
 *
 * O experimento de Wittlinger, Wehner e Wolf (2006): colaram pernas-de-pau em
 * uma turma de formigas do deserto e cortaram as pernas de outra. As de perna
 * longa passaram do ninho; as de perna curta pararam antes — e as duas erraram
 * pela razão exata. Elas contam PASSOS, e a conta é `distância = passos ×
 * tamanho do passo`. Mudou o passo, a conta erra.
 *
 * O gráfico no canto é a assinatura disso: três retas de inclinações diferentes,
 * uma por regime de perna, cortando a linha do ninho em pontos diferentes.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  type EstadoDaViz,
  infoDe,
  limitar,
  numeroDe,
  paleta,
  texto,
  textoDe,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

/** A cor de cada regime, a mesma do rótulo que o renderizador devolve. */
const CORES: Readonly<Record<string, string>> = {
  cotos: '#c2662f',
  normais: '#3aa0ff',
  'pernas-de-pau': '#2f8f5c',
};

/** Tetos das escalas do gráfico. */
const PASSOS_MAX = 60;

/**
 * A formiga de perfil, olhando para onde anda.
 *
 * Três segmentos (cabeça, tórax, gáster), seis pernas e duas antenas. O
 * `escalaPerna` é o que o experimento manipulou: cotos encurtam, pernas-de-pau
 * alongam — e é por isso que ele é parâmetro, e não constante.
 */
function formiga(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  tamanho: number,
  escalaPerna: number,
  tinta: string,
): void {
  const perna = tamanho * 0.9 * escalaPerna;

  ctx.save();
  ctx.translate(x, y);

  ctx.strokeStyle = tinta;
  ctx.lineWidth = Math.max(1, tamanho * 0.11);
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  // As seis pernas, em dois planos, com o joelho para cima.
  for (const lado of [-1, 1]) {
    for (const [ancora, abertura] of [
      [0.5, 1.1],
      [0.05, 1.35],
      [-0.4, 1.1],
    ] as const) {
      ctx.beginPath();
      ctx.moveTo(tamanho * ancora, 0);
      ctx.lineTo(tamanho * ancora + abertura * perna * 0.45, -perna * 0.42);
      ctx.lineTo(tamanho * ancora + abertura * perna * 0.85 * lado, perna);
      ctx.stroke();
    }
  }

  // As antenas.
  ctx.lineWidth = Math.max(0.8, tamanho * 0.08);
  for (const lado of [-1, 1]) {
    ctx.beginPath();
    ctx.moveTo(tamanho * 0.95, -tamanho * 0.15);
    ctx.quadraticCurveTo(
      tamanho * 1.5,
      -tamanho * (0.6 + lado * 0.12),
      tamanho * 1.85,
      -tamanho * (0.3 + lado * 0.3),
    );
    ctx.stroke();
  }

  // Cabeça, tórax e gáster — a silhueta em três nós que faz ler como formiga.
  ctx.fillStyle = tinta;
  for (const [dx, rx, ry] of [
    [-0.95, 0.62, 0.5],
    [0.15, 0.4, 0.32],
    [1, 0.42, 0.38],
  ] as const) {
    ctx.beginPath();
    ctx.ellipse(tamanho * dx, 0, tamanho * rx, tamanho * ry, 0, 0, Math.PI * 2);
    ctx.fill();
  }

  ctx.restore();
}

const podometro: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  /** A reta distância × passos, uma por regime, com o ponto atual em cima. */
  function grafico(
    ctx: CanvasRenderingContext2D,
    L: number,
    A: number,
    alvo: number,
    passo: number,
    passos: number,
    tinta: string,
  ): void {
    const cor = paleta();
    const w = L * 0.3;
    const h = A * 0.32;
    const gx = L - w - 12;
    const gy = A * 0.12;

    ctx.fillStyle = cor.palha;
    ctx.strokeStyle = cor.trilho;
    ctx.lineWidth = 1;
    ctx.fillRect(gx, gy, w, h);
    ctx.strokeRect(gx, gy, w, h);

    const ox = gx + 26;
    const oy = gy + h - 20;
    const ew = w - 36;
    const eh = h - 32;

    ctx.strokeStyle = cor.fraco;
    ctx.beginPath();
    ctx.moveTo(ox, gy + 8);
    ctx.lineTo(ox, oy);
    ctx.lineTo(ox + ew, oy);
    ctx.stroke();

    const miudo = limitar(A * 0.028, 7, 10);
    ctx.save();
    ctx.translate(gx + 9, oy);
    ctx.rotate(-Math.PI / 2);
    texto(ctx, 'distância', 0, 0, miudo, { cor: cor.fraco, alinhamento: 'left' });
    ctx.restore();
    texto(ctx, 'passos', ox + ew / 2, gy + h - 6, miudo, { cor: cor.fraco });

    const distMax = 9 * PASSOS_MAX;
    const sx = (v: number): number => ox + (v / PASSOS_MAX) * ew;
    const sy = (v: number): number => oy - (v / distMax) * eh;

    for (const [regime, mm] of [
      ['cotos', 3],
      ['normais', 5],
      ['pernas-de-pau', 8],
    ] as const) {
      ctx.strokeStyle = CORES[regime] ?? cor.azul;
      ctx.lineWidth = 1.6;
      ctx.beginPath();
      ctx.moveTo(sx(0), sy(0));
      ctx.lineTo(sx(PASSOS_MAX), sy(mm * PASSOS_MAX));
      ctx.stroke();
    }

    ctx.strokeStyle = cor.fraco;
    ctx.setLineDash([3, 3]);
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(ox, sy(alvo));
    ctx.lineTo(ox + ew, sy(alvo));
    ctx.stroke();
    ctx.setLineDash([]);

    ctx.fillStyle = tinta;
    ctx.beginPath();
    ctx.arc(sx(passos), sy(passo * passos), 3.5, 0, Math.PI * 2);
    ctx.fill();
  }

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const passo = numeroDe(valores, 'passo', 0);
    const passos = numeroDe(valores, 'passos', 0);
    const alvo = numeroDe(info, 'alvo', 100);
    const tolerancia = numeroDe(info, 'tol', 4);
    const distancia = passo * passos;
    const ok = info.ok === true;
    const regime = textoDe(info, 'regime') || 'normais';
    const tinta = ok ? cor.verde : (CORES[regime] ?? cor.azul);

    titulo(ctx, L, A, 'distância = passos × tamanho do passo');

    // A areia.
    const solo = A * 0.7;
    const areia = ctx.createLinearGradient(0, solo, 0, A);
    areia.addColorStop(0, '#d9bd86');
    areia.addColorStop(1, '#c2a878');
    ctx.fillStyle = areia;
    ctx.fillRect(0, solo, L, A - solo);

    const x0 = L * 0.08;
    const xFim = L * 0.94;
    // O ninho ocupa ~62% do trecho útil: sobra tela para o "passou do ninho".
    const pxPorMm = ((xFim - x0) * 0.62) / Math.max(1, alvo);
    const ninhoX = x0 + alvo * pxPorMm;
    const formigaX = Math.min(xFim, x0 + distancia * pxPorMm);

    ctx.fillStyle = 'rgb(47 143 92 / 18%)';
    ctx.fillRect(ninhoX - tolerancia * pxPorMm, solo - 46, tolerancia * 2 * pxPorMm, 52);

    ctx.strokeStyle = cor.trilho;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(x0, solo);
    ctx.lineTo(xFim, solo);
    ctx.stroke();

    // Uma pegada por passo, ralcadas para não virar borrão.
    const cada = Math.max(1, Math.ceil(passos / 60));
    ctx.fillStyle = 'rgb(60 40 20 / 45%)';
    for (let i = 1; i <= passos; i += cada) {
      const px = x0 + i * passo * pxPorMm;
      if (px > xFim) break;
      ctx.beginPath();
      ctx.ellipse(px, solo + 6, 2.2, 3.4, 0, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.fillStyle = cor.verde;
    ctx.beginPath();
    ctx.arc(x0, solo, 5, 0, Math.PI * 2);
    ctx.fill();

    // O ninho.
    ctx.fillStyle = '#8a6a44';
    ctx.beginPath();
    ctx.moveTo(ninhoX - 16, solo);
    ctx.lineTo(ninhoX, solo - 20);
    ctx.lineTo(ninhoX + 16, solo);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = cor.texto;
    ctx.beginPath();
    ctx.ellipse(ninhoX, solo - 2, 4, 2.4, 0, 0, Math.PI * 2);
    ctx.fill();

    // A formiga, onde a conta dela mandou parar. O tamanho acompanha a altura
    // da cena: em 8 px de comprimento ela era um borrão de três pontos, e o
    // regime de pernas — que é o assunto do módulo — não se via.
    const respira = Math.sin(t * 3) * 1.2;
    // Cotos, pernas normais ou pernas-de-pau: a perna desenhada segue o regime.
    const escalaPerna = regime === 'cotos' ? 0.6 : regime === 'pernas-de-pau' ? 1.6 : 1;
    formiga(ctx, formigaX, solo - 9 + respira, limitar(A * 0.05, 7, 13), escalaPerna, tinta);

    const miudo = limitar(A * 0.038, 9, 12);
    texto(ctx, `pernas: ${regime}`, formigaX, solo - 34 + respira, miudo, {
      cor: tinta,
      peso: 700,
    });

    texto(
      ctx,
      ok ? 'No ninho ✔' : distancia < alvo ? 'Parou antes do ninho.' : 'Passou do ninho.',
      L / 2,
      A * 0.95,
      limitar(A * 0.044, 10, 14),
      { cor: ok ? cor.verde : cor.fraco, peso: 700 },
    );

    grafico(ctx, L, A, alvo, passo, passos, tinta);
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default podometro;
